__NUXT_JSONP__("/en/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"en",pageTitle:"Accommodations | Mentor Language Institute",pageDescription:"MLI works with U.S. Support Services Inc. to provide housing for MLI students. ",title:"Accommodations",subtitle:["MLI works with U.S. Support Services Inc. to provide housing for MLI students. \u003Cbr \u002F\u003EFor more details, please visit \u003Ca href='https:\u002F\u002Fusssinc.net\u002F' target='_blank'\u003Ewww.usssinc.net\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Students can choose either homestay or dormitory accommodations.",types:[{title:"Dormitory",description:["We provide 40 rooms at our dormitories. There will be a lot of opportunities to communicate with other international students. We recommend you stay in a dormitory if you are on a budget."],lists:["\u003Cb\u003ERoom\u003C\u002Fb\u003E : Private (Individual), Shared (2 people) and Quad (4 people)","\u003Cb\u003EMeal\u003C\u002Fb\u003E : No meals (a fully furnished kitchen is available)","\u003Cb\u003EPrivacy\u003C\u002Fb\u003E : There is more privacy than homestay. There are some dormitory rules.","\u003Cb\u003ECommute\u003C\u002Fb\u003E : about 20 minutes by foot or bus."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Dormitory Prices",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E If younger than 18 years old, the rent will be approximately 10% higher than the price for a person older than 18 years old.",thead:[b,c,"Shared","Quad"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out."]}]},{title:"Homestay",description:["Students who choose to live with a homestay family are looking for a safe, welcoming, and comfortable atmosphere in which they can practice their English skills. It's also an opportunity to learn about American customs, traditions, and family values."],lists:["\u003Cb\u003ERoom\u003C\u002Fb\u003E : Private (Individual)","\u003Cb\u003EMeal\u003C\u002Fb\u003E : 2 meals a day (Breakfast and Dinner)","\u003Cb\u003EPrivacy\u003C\u002Fb\u003E : There are some house rules depending on the host family.","\u003Cb\u003ECommute\u003C\u002Fb\u003E : 30- 45 minutes by bus"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Homestay Prices",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E If younger than 18 years old, the rent will be approximately 10% higher than the price for a person older than 18 years old.",thead:[b,c,"Shared***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out.\u003Cbr \u002F\u003E***If you request a homestay shared room, \u003Cspan class=\"rmarker\"\u003Eyou must apply with another person.\u003C\u002Fspan\u003E"]}]}],comments:{title:"Comments from our staff",description:["It is not easy to find a place to stay when you first arrive in the U.S., especially for international students who do not have a Social Security Number (SSN) and credit history.","Most places require both a SSN and credit history to rent a place.\u003Cbr \u002F\u003ETherefore, we reccommend you stay at our accommodations for at least the first couple of months.","※Your accommodation will be provided by U.S. Support Service Inc. or other agents."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:31.094Z",updatedAt:"2025-05-26T12:06:27.919Z"}}],fetch:{},mutations:void 0}}("$300","","Private","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));